const items = $input.all();
const diasBloqueados = [];

if (!items || items.length === 0) return [];

function extraerHoraLocal(dateTimeStr) {
  const timePart = dateTimeStr.split('T')[1];
  // Maneja tanto formatos con offset (-03:00) como UTC (Z)
  return timePart.replace(/([+-]\d{2}:\d{2}|Z)$/, '').substring(0, 5);
}

function extraerFecha(dateTimeStr) {
  return dateTimeStr.split('T')[0];
}

for (const item of items) {
  // 1. Validar que existan las fechas
  if (!item?.json?.start?.dateTime || !item?.json?.end?.dateTime) continue;

  const data = item.json;
  const inicio = extraerHoraLocal(data.start.dateTime);
  const final  = extraerHoraLocal(data.end.dateTime);
  const dia    = extraerFecha(data.start.dateTime);

  // 2. Agregamos TODOS los eventos sin filtrar por horario exacto
  // Esto incluirá los de 30 min del 9 de abril y los días completos
  diasBloqueados.push({
    json: {
      dia,
      inicio,
      final,
      titulo: data.summary || "Sin título",
      bloqueado: true,
    }
  });
}

return diasBloqueados;

function calcularTurnosDisponibles() {

  // ================= CONFIG =================
  const TOTAL_TURNOS = 20;
  const MAX_DIAS = 6;
  const LIMITE_TARDE = 915; // 15:15
  const HORA_MINIMA = 495;  // 08:15

  const MAX_MANANA = TOTAL_TURNOS / 2;
  const MAX_TARDE = TOTAL_TURNOS / 2;
  const MAX_TURNOS_POR_DIA = Math.ceil(TOTAL_TURNOS / MAX_DIAS);

  // ================= INPUT WORKFLOW =================
  const wfData = $('When Executed by Another Workflow').first().json;
  const modelo = (wfData.modelo || '').trim();
  const km = parseInt(wfData.KM) || 0;

  // ================= TIEMPO SERVICIO =================
  const tiemposPorModeloRaw = $('tiempo_modelo').first().json;

  let TIEMPO_SERVICIO = 30;

  try {
    const mapa = {};
    Object.keys(tiemposPorModeloRaw).forEach(k => {
      mapa[k.toLowerCase()] = tiemposPorModeloRaw[k];
    });

    const modeloKey = modelo.toLowerCase();
    let tiempoStr = mapa[modeloKey];

    if (tiempoStr && tiempoStr.includes(':')) {
      const partes = tiempoStr.split(':').map(Number);
      if (partes.length === 3) {
        const [h, m, s] = partes;
        TIEMPO_SERVICIO = h * 60 + m + (s > 0 ? Math.round(s / 60) : 0);
      } else if (partes.length === 2) {
        const [h, m] = partes;
        TIEMPO_SERVICIO = h * 60 + m;
      }
    }
  } catch (e) {
    TIEMPO_SERVICIO = 30;
  }

  const TIEMPO_LAVADO = 45;
  const TIEMPO_RECEPCION = 15;
  const TIEMPO_PREPARACION = 15;

  // ================= DATOS =================
  const feriados = new Set($('feriados').first().json.feriadosEncontrados || []);
  const tallerData = $('Get row(s) in sheet').first().json;

  const turnosOcupadosRaw = $('Code').all();
  const turnosOcupados = [];
  turnosOcupadosRaw.forEach(i => {
    if (Array.isArray(i.json)) turnosOcupados.push(...i.json);
    else if (i.json?.dia) turnosOcupados.push(i.json);
  });

  // ================= HELPERS =================
  const timeToMinutes = t => {
    const [h, m] = t.split(':').map(Number);
    return h * 60 + m;
  };

  const minutesToTime = m =>
    `${Math.floor(m / 60).toString().padStart(2, '0')}:${(m % 60).toString().padStart(2, '0')}`;

  const formatoFecha = (f) => {
    const d = new Date(f + "T00:00:00");
    const dias = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
    return `${dias[d.getDay()]} ${f.split('-')[2]}/${f.split('-')[1]}`;
  };

  // ================= HORARIOS =================
  const apertura       = Math.max(timeToMinutes(tallerData.Apertura), HORA_MINIMA);
  const cierre         = timeToMinutes(tallerData.Cierre);
  const inicioAlmuerzo = timeToMinutes(tallerData['Inicio Almuerzo']);
  const finAlmuerzo    = timeToMinutes(tallerData['Fin Almuerzo']);
  const inicioDesayuno = timeToMinutes(tallerData['Inicio Desayuno']);
  const finDesayuno    = timeToMinutes(tallerData['Fin Desayuno']);

  // ================= OCUPADOS =================
  const ocupados = new Set();
  turnosOcupados.forEach(t => {
    if (!t.dia || !t.inicio || !t.final) return;
    const ini = timeToMinutes(t.inicio);
    const fin = timeToMinutes(t.final);
    for (let m = ini; m < fin; m++) {
      ocupados.add(`${t.dia}_${minutesToTime(m)}`);
    }
  });

  // ================= VALIDAR TURNO =================
  const estaLibre = (fechaStr, ini) => {
    const fin = ini + TIEMPO_SERVICIO;

    // No puede terminar después del cierre
    if (fin > cierre) return false;

    // No puede solaparse con el almuerzo (ni parcialmente)
    if (ini < finAlmuerzo && fin > inicioAlmuerzo) return false;

    // No puede solaparse con el desayuno (ni parcialmente)
    if (ini < finDesayuno && fin > inicioDesayuno) return false;

    // Verificar slots ocupados minuto a minuto
    for (let m = ini; m < fin; m++) {
      if (ocupados.has(`${fechaStr}_${minutesToTime(m)}`)) return false;
    }

    return true;
  };

  // ================= CALCULAR ENTREGA =================
  const calcularEntrega = (finMecanico) => {
    let entrega = finMecanico + TIEMPO_LAVADO + TIEMPO_PREPARACION;

    // Si el lavado arranca antes del almuerzo y termina dentro o después,
    // se suma el tiempo de almuerzo perdido
    if (finMecanico < inicioAlmuerzo && entrega > inicioAlmuerzo) {
      entrega += (finAlmuerzo - inicioAlmuerzo);
    }

    // Si el lavado arranca dentro del almuerzo, empujar al fin del almuerzo
    if (finMecanico >= inicioAlmuerzo && finMecanico < finAlmuerzo) {
      entrega = finAlmuerzo + TIEMPO_LAVADO + TIEMPO_PREPARACION;
    }

    return entrega;
  };

  // ================= FECHA INICIO (2 DIAS HABILES) =================
  let fecha = new Date();
  fecha.setHours(0, 0, 0, 0);

  let diasHabiles = 0;
  while (diasHabiles < 2) {
    fecha.setDate(fecha.getDate() + 1);
    const d = fecha.getDay();
    const fs = fecha.toISOString().split('T')[0];
    if (d >= 1 && d <= 5 && !feriados.has(fs)) diasHabiles++;
  }

  // ================= BUSQUEDA =================
  const turnos = [];
  let diasBuscados = 0;

  while (turnos.length < 4 && diasBuscados < 60) {

    const fechaStr = fecha.toISOString().split('T')[0];
    const diaSemana = fecha.getDay();

    if (diaSemana >= 1 && diaSemana <= 5 && !feriados.has(fechaStr)) {

      for (let hora = apertura; hora <= LIMITE_TARDE && hora + TIEMPO_SERVICIO <= cierre; hora += 15) {

        if (!estaLibre(fechaStr, hora)) continue;

        const inicio  = hora;
        const fin     = inicio + TIEMPO_SERVICIO;
        const llegada = inicio - TIEMPO_RECEPCION;
        const entrega = calcularEntrega(fin);

        turnos.push({
          dia:            fechaStr,
          inicio:         minutesToTime(inicio),
          final:          minutesToTime(fin),
          horarioLlegada: minutesToTime(llegada),
          horarioEntrega: minutesToTime(entrega),
          fechaFormato:   formatoFecha(fechaStr),
          Id_Calendario:  "248b4f84e12edd9925600aa730446896766a0844543c0199677db45f6fa4a879@group.calendar.google.com"
        });

        break;
      }
    }

    fecha.setDate(fecha.getDate() + 1);
    diasBuscados++;
  }

  return {
    turnosDisponibles: turnos,
    cantidad: turnos.length,
    tiempoServicio: TIEMPO_SERVICIO
  };
}

const resultado = calcularTurnosDisponibles();
return [{ json: resultado }];

function obtenerFeriados() {
  // Obtener los feriados del nodo anterior
  const feriadosData = $input.all(); // Obtiene todos los items del nodo anterior
  const feriados = [];

  // Extraer las fechas de los feriados del formato que recibes
  feriadosData.forEach(item => {
    if (item.json && item.json.start && item.json.start.date) {
      feriados.push(item.json.start.date);
    }
    // Si el feriado dura más de un día, también agregar las fechas intermedias
    if (item.json && item.json.end && item.json.end.date && item.json.start.date !== item.json.end.date) {
      const fechaInicio = new Date(item.json.start.date);
      const fechaFin = new Date(item.json.end.date);

      // Agregar todas las fechas entre inicio y fin
      const fechaActual = new Date(fechaInicio);
      while (fechaActual < fechaFin) {
        feriados.push(fechaActual.toISOString().split('T')[0]);
        fechaActual.setDate(fechaActual.getDate() + 1);
      }
    }
  });

  // Eliminar duplicados de la lista de feriados
  const feriadosUnicos = [...new Set(feriados)];

  return feriadosUnicos;
}

const feriadosEncontrados = obtenerFeriados();

return [{
  json: {
    feriadosEncontrados: feriadosEncontrados
  }
}];

