// ==========================================
// CALCULAR TURNOS DISPONIBLES (AUTOSIGLO)
// ==========================================

function calcularTurnosDisponibles() {

  // ================= CONFIG =================
  const TOTAL_TURNOS = 20;
  const MAX_DIAS = 6;
  const LIMITE_TARDE = 915; // 15:15 (cliente entra a las 15:00)
  const HORA_MINIMA = 495;  // 08:15 (cliente entra a las 08:00)
  const MINUTOS_ANTES_ALMUERZO = 30;

  const MAX_MANANA = TOTAL_TURNOS / 2;
  const MAX_TARDE = TOTAL_TURNOS / 2;
  const MAX_TURNOS_POR_DIA = Math.ceil(TOTAL_TURNOS / MAX_DIAS);

  // ================= INPUT WORKFLOW =================
  const wfData = $('When Executed by Another Workflow').first().json;
  const modelo = (wfData.modelo || '').trim();
  const km = parseInt(wfData.KM) || 0;

  // ================= TIEMPO SERVICIO =================
  const tiemposPorModeloRaw = $('tiempo_modelo').first().json;

  let TIEMPO_SERVICIO = 30;

  try {
    const mapa = {};
    Object.keys(tiemposPorModeloRaw).forEach(k => {
      mapa[k.toLowerCase()] = tiemposPorModeloRaw[k];
    });

    const modeloKey = modelo.toLowerCase();
    let tiempoStr = mapa[modeloKey];

    if (tiempoStr && tiempoStr.includes(':')) {
      const partes = tiempoStr.split(':').map(Number);

      if (partes.length === 3) {
        const [h, m, s] = partes;
        TIEMPO_SERVICIO = h * 60 + m + (s > 0 ? Math.round(s / 60) : 0);
      } else if (partes.length === 2) {
        const [h, m] = partes;
        TIEMPO_SERVICIO = h * 60 + m;
      }
    }

  } catch (e) {
    TIEMPO_SERVICIO = 30;
  }

  const TIEMPO_LAVADO = 45;
  const TIEMPO_RECEPCION = 15;
  const TIEMPO_PREPARACION = 15;

  // ================= DATOS =================
  const feriados = new Set($('feriados').first().json.feriadosEncontrados || []);
  const tallerData = $('Get row(s) in sheet').first().json;

  const turnosOcupadosRaw = $('Code').all();
  const turnosOcupados = [];

  turnosOcupadosRaw.forEach(i => {
    if (Array.isArray(i.json)) turnosOcupados.push(...i.json);
    else if (i.json?.dia) turnosOcupados.push(i.json);
  });

  // ================= HELPERS =================
  const timeToMinutes = t => {
    const [h, m] = t.split(':').map(Number);
    return h * 60 + m;
  };

  const minutesToTime = m =>
    `${Math.floor(m / 60).toString().padStart(2, '0')}:${(m % 60).toString().padStart(2, '0')}`;

  const cruza = (a, b, c, d) => a < d && b > c;

  const formatoFecha = (f) => {
    const d = new Date(f + "T00:00:00");
    const dias = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
    return `${dias[d.getDay()]} ${f.split('-')[2]}/${f.split('-')[1]}`;
  };

  // ================= HORARIOS =================
  const apertura = Math.max(timeToMinutes(tallerData.Apertura), HORA_MINIMA);
  const cierre = timeToMinutes(tallerData.Cierre);

  // Almuerzo fijo 13:00–14:00
  const inicioAlmuerzo = 13 * 60; // 780
  const finAlmuerzo    = 14 * 60; // 840

  const inicioDesayuno = timeToMinutes(tallerData['Inicio Desayuno']);
  const finDesayuno    = timeToMinutes(tallerData['Fin Desayuno']);

  // ================= OCUPADOS =================
  const ocupados = new Set();

  turnosOcupados.forEach(t => {
    for (let m = timeToMinutes(t.inicio); m < timeToMinutes(t.final); m += 15) {
      ocupados.add(`${t.dia}_${minutesToTime(m)}`);
    }
  });

  const estaLibre = (fechaStr, ini, dur) => {
    let duracion = dur;
    const fin = ini + dur;

    if (cruza(ini, fin, inicioAlmuerzo, finAlmuerzo)) {
      duracion += finAlmuerzo - inicioAlmuerzo;
    }

    if (cruza(ini, fin, inicioDesayuno, finDesayuno)) {
      duracion += finDesayuno - inicioDesayuno;
    }

    const finReal = ini + duracion;

    if (finReal > cierre) return false;

    for (let m = ini; m < finReal; m += 15) {
      if (ocupados.has(`${fechaStr}_${minutesToTime(m)}`)) return false;
    }

    return true;
  };

  // ================= FECHA INICIO (2 DIAS HABILES) =================
  let fecha = new Date();
  fecha.setHours(0, 0, 0, 0);

  let diasHabiles = 0;
  while (diasHabiles < 2) {
    fecha.setDate(fecha.getDate() + 1);
    const d = fecha.getDay();
    const fs = fecha.toISOString().split('T')[0];
    if (d >= 1 && d <= 5 && !feriados.has(fs)) diasHabiles++;
  }

  // ================= BUSQUEDA =================
  const turnos = [];
  let diasBuscados = 0;

  while (turnos.length < 4 && diasBuscados < 60) {

    const fechaStr = fecha.toISOString().split('T')[0];
    const diaSemana = fecha.getDay();

    if (diaSemana >= 1 && diaSemana <= 5 && !feriados.has(fechaStr)) {

      // No iniciar turnos después de las 15:15
      for (let hora = apertura; hora <= LIMITE_TARDE && hora + TIEMPO_SERVICIO <= cierre; hora += 15) {

        if (!estaLibre(fechaStr, hora, TIEMPO_SERVICIO)) continue;

        const inicio = hora;
        const fin = inicio + TIEMPO_SERVICIO;
        const llegada = inicio - TIEMPO_RECEPCION;

        let entrega = fin + TIEMPO_LAVADO + TIEMPO_PREPARACION;

        // Si el lavado cruza o cae dentro del almuerzo → sumar 60 min
        if (entrega > inicioAlmuerzo && fin <= inicioAlmuerzo) {
          entrega += finAlmuerzo - inicioAlmuerzo;
        } else if (entrega > inicioAlmuerzo && entrega <= finAlmuerzo) {
          entrega = finAlmuerzo;
        }

        turnos.push({
          dia: fechaStr,
          inicio: minutesToTime(inicio),
          final: minutesToTime(fin),
          horarioLlegada: minutesToTime(llegada),
          horarioEntrega: minutesToTime(entrega),
          fechaFormato: formatoFecha(fechaStr),
          Id_Calendario: "248b4f84e12edd9925600aa730446896766a0844543c0199677db45f6fa4a879@group.calendar.google.com"
        });

        break;
      }
    }

    fecha.setDate(fecha.getDate() + 1);
    diasBuscados++;
  }

  return {
    turnosDisponibles: turnos,
    cantidad: turnos.length,
    tiempoServicio: TIEMPO_SERVICIO
  };
}

// ================= OUTPUT =================
const resultado = calcularTurnosDisponibles();

return [{
  json: resultado
}];
